import{_ as n,C as e,c as r,o as p,aa as o,G as a}from"./chunks/framework.Cn7WEiMX.js";const y=JSON.parse('{"title":"Dynmap 上的加速区域","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/setup/guides/boosting-areas-on-dynmap.md","filePath":"wiki/Dynmap/setup/guides/boosting-areas-on-dynmap.md"}'),l={name:"wiki/Dynmap/setup/guides/boosting-areas-on-dynmap.md"};function c(i,t,m,g,_,f){const d=e("NolebaseGitContributors"),s=e("NolebaseGitChangelog");return p(),r("div",null,[t[0]||(t[0]=o('<h1 id="dynmap-上的加速区域" tabindex="-1">Dynmap 上的加速区域 <a class="header-anchor" href="#dynmap-上的加速区域" aria-label="Permalink to &quot;Dynmap 上的加速区域&quot;">​</a></h1> <p>本章节的教程将会简要讲述如何加速渲染 Dynmap 上的指定区域。</p> <p>第一步，准备需要加速的地图：在编辑任何地图数据之前，请先输入命令：<code>/dynmap pause all</code></p> <p>通过这个命令设置地图加速增量：<code>/dmap mapset &lt;世界名称&gt;:&lt;地图名称&gt; boostzoom:&lt;x&gt;</code>，<code>x</code> 可为 0-3 之间的值，每个值都会增加加速值，所以，若需要从 16 ppb<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> 增加到 64 ppb，你需要将它设置为 2。</p> <p>第二步，添加加速区域：通过 <code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt; &lt;世界名称&gt;</code> 选择第一个角点，<code>/dmarker addcorner &lt;x&gt; &lt;y&gt; &lt;z&gt;</code> 选择第二个角点，最后通过命令 <code>/dmarker addarea &lt;区域名称&gt; boost:true</code> 创建区域并将其设置为加速区域。</p> <p>矩形区域只需要设置两个角点，若需要设置多边形区域，你需要自行添加角点。若需要设置圆形区域，你可以使用这个命令：<code>/dmarker addcircle &lt;标点 ID&gt; radius:&lt;半径&gt; world:&lt;世界名称&gt; x:&lt;x&gt; y:&lt;y&gt; z:&lt;z&gt; boost:true</code>。</p> <p>在确认需要设置的位置后，可以将它们的 <code>fillopacity</code> 与 <code>opacity</code> 通过命令 <code>/dmarker updatearea &lt;标点 ID&gt; fillopacity:0.0 opacity:0.0</code> 设置为透明。</p> <p><code>&lt;标点 ID&gt;</code> 可通过 <code>/dmarker listareas</code> 查看。</p> <p>第三步，输入命令 <code>/dynmap pause none</code> 重新开始所有渲染任务。</p> <p>第四步，可通过 <code>/dynmap fullrender &lt;世界名称&gt;:&lt;地图名称&gt;</code> 或 <code>/dynmap radiusrender &lt;世界名称&gt; &lt;x&gt; &lt;z&gt; &lt;半径&gt;</code> 命令渲染加速区域。</p> ',20)),a(d),a(s),t[1]||(t[1]=o('<hr class="footnotes-sep"> <section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Pixels Per Block，即“每方块边缘像素数”。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li></ol></section>',3))])}const b=n(l,[["render",c]]);export{y as __pageData,b as default};
